package org.freecad.mobilelab;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.zip.*;
public final class GraphRegression {
 static int checks;interface Action{void run()throws Exception;}static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}static void near(double a,double b){check(Math.abs(a-b)<1e-5,"Expected "+b+" got "+a);}static void reject(Action a)throws Exception{try{a.run();}catch(Exception e){checks++;return;}throw new AssertionError("Invalid graph accepted");}
 static JSONObject node(int id,String kind,double value,int...in)throws Exception{return new JSONObject().put("id",id).put("kind",kind).put("value",value).put("inputs",new JSONArray(in));}
 static String graph(JSONArray nodes,int output)throws Exception{return new JSONObject().put("version",1).put("nodes",nodes).put("outputs",new JSONArray().put(output)).toString();}
 static JSONObject obj(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new AssertionError("missing");}
 static void tx(Action a)throws Exception{String workspace=ProjectStore.workspace();NativeCad.beginTransaction(true);try{a.run();NativeCad.setWorkspace(ProjectStore.workspace());NativeCad.commitTransaction();}catch(Throwable x){NativeCad.rollbackTransaction();ProjectStore.applyWorkspace(workspace);throw x;}}
 public static void main(String[] args)throws Exception{
  NativeCad.clear();ProjectStore.reset();check(ParametricGraph.KINDS.length==40,"Expected 40 components");String g=ParametricGraph.example();int ring=ParametricGraph.evaluate(g,new int[0]);ProjectStore.graphJson=g;ProjectStore.graphOutputIds=ParametricGraph.lastOutputs.clone();NativeCad.setWorkspace(ProjectStore.workspace());double v=obj(ring).getDouble("volume");final String variant=ParametricGraph.variant(g,1,20);tx(()->{int id=ParametricGraph.evaluate(variant,ProjectStore.graphOutputIds);ProjectStore.graphJson=variant;ProjectStore.graphOutputIds=ParametricGraph.lastOutputs.clone();check(obj(id).getDouble("volume")>v,"Variant did not update");});NativeCad.undo();ProjectStore.applyWorkspace(NativeCad.getWorkspace());check(new JSONObject(ProjectStore.graphJson).toString().equals(new JSONObject(g).toString()),"Graph recipe Undo");NativeCad.redo();ProjectStore.applyWorkspace(NativeCad.getWorkspace());check(new JSONObject(ProjectStore.graphJson).toString().equals(new JSONObject(variant).toString()),"Graph recipe Redo");
  JSONArray nodes=new JSONArray().put(node(1,"Number",0)).put(node(2,"Number",10)).put(node(3,"Number",6)).put(node(4,"Range",0,1,2,3)).put(node(5,"Number",3)).put(node(6,"List item",0,4,5)).put(node(7,"Circle",0,6));String ranges=graph(nodes,7);near(ParametricGraph.inspect(ranges,6).n,6);nodes.getJSONObject(4).put("value",6);final String badIndex=graph(nodes,7);reject(()->ParametricGraph.inspect(badIndex,6));nodes.getJSONObject(4).put("value",3);nodes.getJSONObject(3).put("kind","Series");near(ParametricGraph.inspect(graph(nodes,7),6).n,30);
  nodes=new JSONArray().put(node(1,"Number",0)).put(node(2,"Number",2)).put(node(3,"Number",4)).put(node(4,"Point",0,1,1,1)).put(node(5,"Point",0,2,1,1)).put(node(6,"Point series",0,4,5,3)).put(node(7,"NURBS curve",0,6)).put(node(8,"Number",.5)).put(node(9,"Curve point",0,7,8));String points=graph(nodes,7);ParametricGraph.validate(points);double[] xyz=ParametricGraph.inspect(points,9).data;near(xyz[0],3);near(xyz[1],0);check(ParametricGraph.inputType("Point series",0).equals("point"),"Point port type");check(!ParametricGraph.compatible("Point series",0,"Number"),"Wrong numeric connection accepted");nodes.getJSONObject(5).getJSONArray("inputs").put(0,1);final String wrong=graph(nodes,7);reject(()->ParametricGraph.validate(wrong));
  nodes=new JSONArray().put(node(1,"Number",20)).put(node(2,"Number",16)).put(node(3,"Number",8)).put(node(4,"Patch",0,1,2,3)).put(node(5,"Number",.5)).put(node(6,"Surface point",0,4,5,5));double[] centre=ParametricGraph.inspect(graph(nodes,4),6).data;near(centre[0],0);near(centre[1],0);near(centre[2],2);
  nodes=new JSONArray().put(node(1,"Number",10)).put(node(2,"Number",0)).put(node(3,"Divide",0,1,2)).put(node(4,"Circle",0,3));final String division=graph(nodes,4);reject(()->ParametricGraph.inspect(division,3));nodes.getJSONObject(2).put("kind","Sin").put("inputs",new JSONArray().put(1));near(ParametricGraph.inspect(graph(nodes,4),3).n,Math.sin(Math.toRadians(10)));
  NativeCad.clear();ProjectStore.reset();int saved=ParametricGraph.evaluate(g,new int[0]);ProjectStore.graphJson=g;ProjectStore.graphOutputIds=ParametricGraph.lastOutputs.clone();NativeCad.setWorkspace(ProjectStore.workspace());tx(()->NativeCad.move(saved,1,0,0));NativeCad.undo();ProjectStore.applyWorkspace(NativeCad.getWorkspace());String before=NativeCad.objects(),workspace=NativeCad.getWorkspace();File root=Files.createTempDirectory("graph-recipes-").toFile(),cache=new File(root,"cache");cache.mkdir();try{File recipe=new File(root,"ring.cadgraph");RecipeFiles.write(recipe,g);ParametricGraph.validate(RecipeFiles.read(recipe));check(new JSONObject(RecipeFiles.read(recipe)).getInt("version")==1,"Recipe version lost");File zip=new File(root,"variants.zip");NativeCad.beginTransaction(false);try{RecipeFiles.batch(zip,cache,g,1,16,20,3,.05);NativeCad.commitTransaction();}catch(Throwable x){NativeCad.rollbackTransaction();throw x;}check(NativeCad.objects().equals(before)&&NativeCad.getWorkspace().equals(workspace),"Batch altered scene/workspace");try(ZipFile z=new ZipFile(zip)){check(z.size()==6,"Batch entries absent");double[] diameters={16,18,20};for(int i=0;i<3;i++){check(z.getEntry("variant-"+(i+1)+".stl").getSize()>84,"Empty STL variant");try(InputStream in=z.getInputStream(z.getEntry("variant-"+(i+1)+".cadgraph"))){ByteArrayOutputStream b=new ByteArrayOutputStream();ArchiveIO.copy(in,b,256000,null);JSONObject r=new JSONObject(new String(b.toByteArray(),"UTF-8"));near(r.getJSONObject("graph").getJSONArray("nodes").getJSONObject(0).getDouble("value"),diameters[i]);}}}check(NativeCad.redo(),"Batch destroyed Redo history");check(cache.list().length==0,"Batch leaked files");NativeCad.beginTransaction(false);try{reject(()->RecipeFiles.batch(zip,cache,g,99,16,20,3,.05));NativeCad.commitTransaction();}catch(Throwable x){NativeCad.rollbackTransaction();throw x;}}finally{ArchiveIO.deleteTree(root);}
  System.out.println("PASS: "+checks+" graph assertions: typed point/list ports, range/series/list indexing, curve/surface evaluation, math rejection, recipe versions, graph Undo/Redo, STL batch variants and scene/history preservation");
 }
}
